(select ACCOUNT_NUMBER,CUSTOMER_ID,AMOUNT_LCY as SepSalaryAmt,DEBIT_CUSTOMER,
COALESCE(NULLIF(PAYMENT_DETAILS, ''), THEIR_REFERENCE, CREDIT_THEIR_REF, NARRATIVE) AS Sep_PAYMENT_DETAILS_Narration,
